<?php if ( ! defined('BASEPATH')) exit('No direct script access allowed');class menquiry extends CI_Controller {    private $limit = 3;    public $companyid = 0;    public $loggeduserid = 0;    public function __construct() {        parent::__construct();        $this->load->helper('xssclean');        $this->load->model("commonmodel");        error_reporting(E_ALL);        $this->load->model(CNFCOMPANY.'menquirymodel');        fnIfCheckUserLoggedIn();        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $this->loggeduserid   = $ArrUserLoggedInfo['id'];        $this->companyid   = $ArrUserLoggedInfo['companyid'];    }    public function manageenquiry() {        $ArrBB						                    = $this->commonmodel->fnGetBuyerAndBrand();        $ArrData = array('ArrBB'=>$ArrBB,'ArrMerchants'=>$this->menquirymodel->getMerchantData($this->companyid,1));        $VarFrom											    = xssclean($this->input->post('rfrom'));        if($VarFrom==1) {            $VarEnType											    = xssclean($this->input->post('entype'));            $VarStyleref  											= xssclean($this->input->post('styleref'));            $VarIsrior  										    = xssclean($this->input->post('isrior'));            $VarBuyerbrand  									    = xssclean($this->input->post('bb'));            $VarMercn  											    = xssclean($this->input->post('mercn'));            $VarUserType  											    = xssclean($this->input->post('ut'));            $VarEnqFrom = ''; $VarEnqTo = '';            if(xssclean($this->input->post('reqfrom')) != "") {                $VarEnqFrom  									    	= date('Y-m-d H:i:s',strtotime(xssclean($this->input->post('reqfrom'))));            }            if(xssclean($this->input->post('reqto')) != "") {                $VarEnqTo = date('Y-m-d H:i:s', strtotime(xssclean($this->input->post('reqto'))));            }            $VarStatus  											= xssclean($this->input->post('s'));            $clickedColumnId  										= xssclean($this->input->post('columnId'));            if($clickedColumnId == 5) {            }            $newsortorder  										    = xssclean($this->input->post('sortorder'));            $VarAfilter  										    = xssclean($this->input->post('afilter'));            $VarURLSegment										= 4;            $this->load->library('pagination');            $config['base_url']									= base_url().CNFCOMPANY.'menquiry/manageenquiry/';            $config['total_rows']								= $this->menquirymodel->fnCount($VarUserType,$VarEnType,$VarStyleref,$VarIsrior,$VarBuyerbrand,$VarMercn,$VarEnqFrom,$VarEnqTo,$VarStatus,$VarAfilter);            $config['per_page']									= $this->limit;            $config['uri_segment']								= $VarURLSegment;            $offset												= $this->uri->segment($VarURLSegment);            $this->pagination->initialize($config);            $sortby												= "dateupdated";            $sortorder											= "desc";            $ArrDbCols = array('1'=>'et.enquirytype','2'=>'e.reqforisrior','3'=>'e.datecreated','4'=>'e.stylenamerefno','5'=>'brandname','6'=>'confirmprice','7'=>'currency','8'=>'contactname','9'=>'orderstatus','10'=>'dateupdated','11'=>'status');            if($clickedColumnId <> '' && $newsortorder <> '') {                if(array_key_exists($clickedColumnId,$ArrDbCols)) {                    $sortby = $ArrDbCols[$clickedColumnId];                }                $sortorder = $newsortorder;            }            $ArrEnqList								    = $this->menquirymodel->fnList($VarUserType,$VarEnType,$VarStyleref,$VarIsrior,$VarBuyerbrand,$VarMercn,$VarEnqFrom,$VarEnqTo,$VarStatus,$this->limit,$offset,$sortby,$sortorder,$VarAfilter);            $data['pagination']									= $this->pagination->create_linkswithajax('EnList');            $i=0;            $ArrFnlList										    = array();            $ArrStatus                                          = unserialize(ARRSTATUS);            $ArrIsrIor                                          = unserialize(ARRISRIOR);            $ArrCurrecnyList                                    = unserialize(ARRCURRENCYLIST);            $ArrEnquiryStatus = unserialize(ORDERENQUIRYSTATUS);            foreach ($ArrEnqList['enq'] as $key => $ObjFabric) {                $ArrFnlList[$i]['id']						    = $ObjFabric->id;                $ArrFnlList[$i]['enqt']						    = $ObjFabric->enq;                $ArrFnlList[$i]['enqmode']						= $ObjFabric->modeofenquiry;                $VarBB						                    = $this->commonmodel->fnGetBuyerAndBrand($ObjFabric->brandbuyerid);                $ArrFnlList[$i]['bb']						    = $VarBB[0]->brandname . ' / ' . $VarBB[0]->buyername;                if($ObjFabric->orderstatus == '1') {                    $ArrFnlList[$i]['ano']                      = '<span class="text-light bg-dark"><strong>'.$ArrEnquiryStatus[$ObjFabric->orderstatus].'</strong></span>';                }                elseif ($ObjFabric->orderstatus == '2')                    $ArrFnlList[$i]['ano']                      = $ArrEnquiryStatus[$ObjFabric->orderstatus];                elseif ($ObjFabric->orderstatus == '3')                    $ArrFnlList[$i]['ano']                      = '<span class="text-danger"><strong>'.$ArrEnquiryStatus[$ObjFabric->orderstatus].'</strong></span>';                elseif ($ObjFabric->orderstatus == '4')                    $ArrFnlList[$i]['ano']                      = '<div class="p-3 mb-2 bg-warning text-dark"><strong>'.$ArrEnquiryStatus[$ObjFabric->orderstatus].'</strong></div>';                $ArrFnlList[$i]['styref']					    = '<span class="text-danger"><strong>'.$ObjFabric->stylenamerefno.'</strong></span>';                $ArrFnlList[$i]['mname']					    = $ObjFabric->contactname;                $ArrFnlList[$i]['curr']					        = $ObjFabric->currency == '0' ? '' : $ArrCurrecnyList[$ObjFabric->currency];                $ArrFnlList[$i]['isrior']					    = @$ArrIsrIor[$ObjFabric->reqforisrior];                $ArrFnlList[$i]['cfmpr']					    = $ObjFabric->confirmprice;                $ArrFnlList[$i]['s']						    = $ArrStatus[$ObjFabric->status];                $ArrFnlList[$i]['drequested']					= date('d-m-Y / H:i:s',strtotime($ObjFabric->daterequested));                $ArrFnlList[$i]['dateauth']						= $ObjFabric->dateauthorized == '' ? '-' : date('d-m-Y / H:i:s',strtotime($ObjFabric->dateauthorized));                $i++;            }            echo json_encode(array('errcode'=>1,'cn'=>$config['total_rows'],'ct'=>$i,'re'=>$ArrFnlList,'pa'=>base64_encode($data['pagination'])));            unset($ArrFnlList);            die;        } else {            $this->load->view(CNFCOMPANY.'manageenquiry',$ArrData);        }    }    public function enquiryview() {        $this->load->model('commonmodel');        $ArrUserLoggedInfo                                      = fnGetUserLoggedInfo('1');        $this->companyid                                        = $ArrUserLoggedInfo['companyid'];        $VarId		    									    = $this->uri->segment(4);        if($VarId <>'' && base64_decode(urldecode($VarId))) {            $VarEnquiryId   = base64_decode(urldecode($VarId));            $ResEnquiry = $this->menquirymodel->fnGetInfo('', $VarEnquiryId, $this->companyid);            $ObjEnquiry = $ResEnquiry['et'][0];            $ObjBuyer   = $ResEnquiry['buyer'][0];            $ArrCountryList  = unserialize(ARRCOUNTRYLIST);            $ArrCurrencyList = unserialize(ARRCURRENCYLIST);            $ArrIsrIor       = unserialize(ARRISRIOR);            $ArrPcsorSet     = unserialize(ARRPCSSET);            $ArrOrderStatus  = unserialize(ORDERENQUIRYSTATUS);        }        $VarHashId = $this->uri->segment(4);        $VarEnqId = base64_decode(urldecode($VarHashId));        $ResObj = $this->menquirymodel->fnEnqLogList($VarEnqId,$this->companyid);        $this->load->view(CNFCOMPANY.'orderenquiryview',array('ObjEnquiry'=>$ObjEnquiry,'ObjBuyer'=>$ObjBuyer,'VarIsrIor'=>$ArrIsrIor[$ObjEnquiry->reqforisrior],            'VarIsrIorId'=>$ObjEnquiry->reqforisrior,'VarCurrency'=>@$ArrCurrencyList[$ObjEnquiry->currency],'VarCountry'=>@$ArrCountryList[$ObjEnquiry->countryid],            'VarHashId'=>$VarHashId,'VarPcsorSet'=>@$ArrPcsorSet[$ObjEnquiry->pcsorset],'VarEnquiryId'=>$VarEnquiryId,'ArrOrderStatus'=>$ArrOrderStatus,'ResObj'=>$ResObj));    }    function changemStatus() {        $VarActDeactOption										= xssclean($this->input->post('actdeact'));        $VarCid 	   										    = xssclean($this->input->post('cid'));        if($VarActDeactOption <> '' && $VarCid <> '') {            if($this->menquirymodel->fnChangeStatus($VarCid,$VarActDeactOption)) {                echo json_encode(array('errcode'=> 1));                die;            }            else                 echo json_encode(array('errcode'=> -1));        }    }    function fnUploadAttachment()    {        $VarFdrName = $_POST['enq'];        $VarDir = $_SERVER['DOCUMENT_ROOT'] . "/uploads/orderenquiry/".$VarFdrName."/";        if(!file_exists($VarDir)) {            mkdir($VarDir,0777,true);        }            if (isset($_FILES["myfile"])) {                $ret = array();                $error = $_FILES["myfile"]["error"];                //You need to handle  both cases                //If Any browser does not support serializing of multiple files using FormData()                if (!is_array($_FILES["myfile"]["name"])) //single file                {                    $fileName = $_FILES["myfile"]["name"];                    move_uploaded_file($_FILES["myfile"]["tmp_name"], $VarDir . $fileName);                    $ret[] = $fileName;                } else  //Multiple files, file[]                {                    $fileCount = count($_FILES["myfile"]["name"]);                    for ($i = 0; $i < $fileCount; $i++) {                        $fileName = $_FILES["myfile"]["name"][$i];                        move_uploaded_file($_FILES["myfile"]["tmp_name"][$i], $VarDir . $fileName);                        $ret[] = $fileName;                    }                }                //echo '<pre>'; print_r($ret); die('');                echo json_encode($ret);            }    }    function download()    {        $VarId										= xssclean($this->input->get('enqid'));        $filename										= xssclean($this->input->get('filename'));        if(isset($filename))        {            $fileName=$_GET['filename'];            $fileName=str_replace("..",".",$fileName); //required. if somebody is trying parent folder files            $file = $_SERVER['DOCUMENT_ROOT'] . "/uploads/orderenquiry/".$VarId."/".$fileName;            $file = str_replace("..","",$file);            if (file_exists($file)) {                $fileName =str_replace(" ","",$fileName);                header('Content-Description: File Transfer');                header('Content-Disposition: attachment; filename='.$fileName);                header('Content-Transfer-Encoding: binary');                header('Expires: 0');                header('Cache-Control: must-revalidate');                header('Pragma: public');                header('Content-Length: ' . filesize($file));                ob_clean();                flush();                readfile($file);                exit;            }        }    }    function fnCheckPin() {        $this->load->model('commonmodel');        $VarPw										= xssclean($this->input->post('i'));        $ArrUserLoggedId                            = fnGetUserLoggedInfo(1);        $this->companyid                            = $ArrUserLoggedId['companyid'];        $ArrIsrIor                                  = unserialize(ARRISRIOR);        if($this->commonmodel->fnValidatePin($ArrUserLoggedId['id'],$VarPw)) {            $VarEnquiryId                           = xssclean($this->input->post('enqid'));            $VarRefType                             = xssclean($this->input->post('ty'));            $VarApprStatus                          = xssclean($this->input->post('s'));            $VarComments                            = addslashes(xssclean($this->input->post('c')));            $VarAssignedNo = 0;            $ArrRes                                    = $this->menquirymodel->fnAuthorize($this->companyid,$VarEnquiryId,$VarApprStatus,$VarComments,$VarRefType);            if($ArrRes <> '') {                echo json_encode(array('errcode'=>'1','assignedno'=>$ArrRes,'dupdated'=>date('d-m-Y / H:i:s')));            }            else {                echo json_encode(array('errcode'=>'1','assignedno'=>'0','dupdated'=>date('d-m-Y / H:i:s')));            }        }        else {            echo json_encode(array('errcode'=>'-1','msg'=>'Invalid PIN'));        }    }    function fnLogList() {        $ArrUserLoggedInfo      = fnGetUserLoggedInfo('1');        $this->companyid           = $ArrUserLoggedInfo['companyid'];        $VarFrom                = xssclean($this->input->post('rfrom'));        $VarEnquiryId           = xssclean($this->input->post('enquiryid'));        if($VarFrom == '1') {            $clickedColumnId  										= xssclean($this->input->post('columnId'));            $newsortorder  										    = xssclean($this->input->post('sortorder'));            $VarAfilter  										    = xssclean($this->input->post('afilter'));            $VarURLSegment										= 4;            $this->load->library('pagination');            $config['base_url']									= base_url().CNFCOMPANY.'menquiry/fnLogList/';            $config['total_rows']								= $this->menquirymodel->fnCountEnquiryLog($VarEnquiryId,$this->companyid);            $config['per_page']									= $this->limit;            $config['uri_segment']								= $VarURLSegment;            $offset												= $this->uri->segment($VarURLSegment);            $this->pagination->initialize($config);            $sortby												= "dateupdated";            $sortorder											= "desc";            $data['pagination']									= $this->pagination->create_linkswithajax('EnLogList');            $ArrDbCols = array('1'=>'e.datecreated','2'=>'orderstatus','3'=>'comments');            if($clickedColumnId <> '' && $newsortorder <> '') {                if(array_key_exists($clickedColumnId,$ArrDbCols)) {                    $sortby = $ArrDbCols[$clickedColumnId];                }                $sortorder = $newsortorder;            }            $ArrFnlList = array(); $i = 0; $ArrOrderStatus = unserialize(ORDERENQUIRYSTATUS);            $ArrEnquiryLog = $this->menquirymodel->fnEnqLogList($VarEnquiryId,$this->companyid);            foreach ($ArrEnquiryLog as $key => $ObjFabric) {                $ArrFnlList[$i]['id']						    = $ObjFabric->id;                $ArrFnlList[$i]['enquiryid']					= $ObjFabric->enquiryid;                $ArrFnlList[$i]['sd']						    = date('d-m-Y',strtotime($ObjFabric->datecreated));                $ArrFnlList[$i]['as']						    = $ArrOrderStatus[$ObjFabric->orderstatus];                $ArrFnlList[$i]['comm']						    = $ObjFabric->comments;                $i++;            }            echo json_encode(array('errcode'=>1,'cn'=>$config['total_rows'],'ct'=>$i,'re'=>$ArrFnlList,'pa'=>base64_encode($data['pagination'])));            unset($ArrFnlList); die();        }    }    function enquirylogdetail() {        $VarFrom = xssclean($this->input->post('rfrom'));        $VarEnqLogId = xssclean($this->input->post('lid'));        $ArrEnqLog = $this->menquirymodel->fnGetEnqLog($VarEnqLogId);        if($VarFrom == '1') {            if($ArrEnqLog) {                $ArrFinal         = array();                $ArrCurrency      = unserialize(ARRCURRENCYLIST);                $ArrIsrIor        = unserialize(ARRISRIOR);                $ArrPcsorSet      = unserialize(ARRPCSSET);                $ArrCountryList   = unserialize(ARRCOUNTRYLIST);                $ArrOrderStatus   = unserialize(ORDERENQUIRYSTATUS);                $VarBB            = @$ArrEnqLog['et']->brandname . ' / ' . @$ArrEnqLog['buyer']->buyername;                $VarConty         = $ArrCountryList[$ArrEnqLog['et']->countryid];                $VarReqDt         = $ArrEnqLog['et']->daterequested == '' ? '-' : date('d-m-Y / H:i:s', strtotime($ArrEnqLog['et']->daterequested));                $VarAuthUpdate    = $ArrEnqLog['et']->dateauthorized == '' ? '-' : date('d-m-Y / H:i:s', strtotime($ArrEnqLog['et']->dateauthorized));                $VarCurrency      = $ArrEnqLog['et']->currency == '0' ? '' : $ArrCurrency[$ArrEnqLog['et']->currency];                $VarPcsorSet      = $ArrPcsorSet[$ArrEnqLog['et']->pcsorset];                $Varreqforisrior  = $ArrIsrIor[$ArrEnqLog['et']->reqforisrior];                $VarCurrentStatus = $ArrOrderStatus[$ArrEnqLog['et']->orderstatus];                $VarFdr           = FCPATH . "uploads/orderenquiry/" . $ArrEnqLog['et']->enquiryid;                if (file_exists($VarFdr)) {                    if ($dh = opendir($VarFdr)) {                        while (($file = readdir($dh)) !== false) {                            if ($file != "." && $file != "..") {                                $ArrDownloads[] = array('id' => $ArrEnqLog['et']->enquiryid, 'fn' => $file);                            }                        }                        closedir($dh);                    }                } else {                    $ArrDownloads = array();                }                echo json_encode(array('logdetaildata' => array('VarEnqLogId' => $VarEnqLogId, 'styleref' => $ArrEnqLog['et']->stylenamerefno,                    'styledesc' => $ArrEnqLog['et']->styledesc, 'mcomm' => $ArrEnqLog['et']->comments, 'enqdt' => date('d-m-Y', strtotime($ArrEnqLog['et']->enquirydate)),                    'enqtype' => $ArrEnqLog['et']->enquirytype, 'enqmode' => $ArrEnqLog['et']->modeofenquiry, 'mnote' => $ArrEnqLog['et']->merchantnote, 'mname' =>                        $ArrEnqLog['et']->contactname, 'pqty' => $ArrEnqLog['et']->exporderqty, 'qp' => $ArrEnqLog['et']->quotedprice, 'bp' => $ArrEnqLog['et']->buyerprice,                    'cp' => $ArrEnqLog['et']->confirmprice, 'pcsset' => $VarPcsorSet, 'isrior' => $Varreqforisrior, 'currency' => $VarCurrency, 'VarCurrentStatus' => $VarCurrentStatus,                    'conty' => $VarConty, 'enquiryid' => $ArrEnqLog['et']->enquiryid, 'bb' => $VarBB, 'lgreqdt' => $VarReqDt, 'lgreupdate' => $VarAuthUpdate, 'orstatus' => $ArrEnqLog['et']->orderstatus),                    'downloads' => $ArrDownloads));            }            else {                echo json_encode(array('logdetaildata'=>array('errcode'=>'-1')));            }        }    }    function tempcreatetable() {        $ArrCurrecnyList                                    = unserialize(ARRCURRENCYLIST);        foreach($ArrCurrecnyList as $item) {            $this->db->insert();        }    }}